with unpacked as (select id, host, coalesce(context['version'], 'direct') as version_or_default, array_contains(map_keys(context), 'version') as has_version, get_json_object(payload_json, '$.user.tier') as user_tier from app_logs) select host, size(collect_set(host)) as num_hosts, sort_array(collect_set(host)) as host_list, count(*) filter (where host = 'h1') as h1_rows, count(*) filter (where host = 'h3') as h3_rows, count(case when host = 'h3' then 1 end) as h3_count from unpacked group by host order by h1_rows
